Object.assign(SNIP,{});PRESET_NOTES["l57"]={"Ví dụ: Bellman-Ford": "dist = 0 3 7 5 4. Đường tới 2 rẻ nhất là 1 → 3 → 2 (7 − 4 = 3), ngắn hơn cạnh thẳng 6; Dijkstra sẽ chốt 2 với 6 trước khi thấy cạnh âm. Đỉnh 4: 1 → 3 → 5 → 4 dài 7 − 3 + 1 = 5. Cạnh cam là cạnh đang nới.", "Ví dụ: Dừng sớm khi không còn gì đổi": "Chỉ chạy 2 vòng thay vì 4: thứ tự các cạnh thuận lợi nên vòng đầu đã ra hết khoảng cách, vòng thứ 2 không nới được gì nữa. Trong thực tế thường dừng sớm hơn nhiều so với n − 1 vòng, nhưng trường hợp xấu nhất vẫn là O(n · m).", "Ví dụ: Phát hiện chu trình âm": "Đi vòng 2 → 3 → 4 → 2 mỗi lần bớt 1, nên khoảng cách giảm mãi. Sau n − 1 vòng vẫn còn cạnh nới được ở vòng thứ n: đó là bằng chứng có chu trình âm.", "Ví dụ: Đi tối đa k cạnh": "Chỉ được dừng giữa đường tối đa 1 lần (đi ≤ 2 cạnh): đường 1 → 2 → 3 → 4 (dài 3) không dùng được, đáp án 2 qua 1 → 2 → 4. Nếu nới trực tiếp trên dist thay vì bản sao cu, một vòng có thể đi liền nhiều cạnh và vượt giới hạn.", "Lỗi: nới từ đỉnh chưa tới được": "Lúc xét cạnh 2 → 3, đỉnh 2 chưa tới được (dist = INF), nhưng INF − 5 < INF nên dist[3] thành 999999995: một khoảng cách giả từ hư không. Luôn kiểm tra dist[u] ≠ INF trước khi nới."};EX_HINTS["l57"]=[["Cạnh âm nên Dijkstra không dùng được. Bellman-Ford: n − 1 vòng, mỗi vòng nới mọi cạnh.", "Chỉ nới cạnh u → v khi dist[u] ≠ INF.", "Thêm cờ “vòng này có đổi gì không” để dừng sớm."], ["Vòng có thể ở bất kỳ đâu, không nhất thiết tới được từ món 1: khởi tạo dist = 0 cho mọi đỉnh (như một nguồn ảo nối tới tất cả).", "Chạy n − 1 vòng nới, rồi thêm vòng thứ n: còn cạnh nới được thì có chu trình âm.", "Khuyên u → u có w < 0 cũng là chu trình âm."], ["Sau vòng thứ i của Bellman-Ford (nới đúng cách), dist[v] là giá rẻ nhất dùng tối đa i chuyến. Chạy k + 1 vòng.", "Mỗi vòng phải nới từ bản sao cu của vòng trước: nới trực tiếp trên dist có thể đi liền nhiều chuyến trong một vòng.", "Dijkstra thường không giữ được ràng buộc số chặng (đường rẻ nhất có thể dùng quá nhiều chặng)."]];
/* ===================== BÀI 57 · Thuật toán Bellman-Ford và chu trình âm ===================== */
/* Bài 57 · Thuật toán Bellman-Ford và chu trình âm
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR57=[{label:"Ví dụ: Bellman-Ford",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n = 5, m = 7;\n    int eu[7] = {1, 1, 2, 3, 3, 4, 5};\n    int ev[7] = {2, 3, 4, 2, 5, 5, 4};\n    int ew[7] = {6, 7, 5, -4, -3, 2, 1};\n    const long long INF = 4e18;\n    vector<long long> dist(n + 1, INF);\n    dist[1] = 0;\n    for (int vong = 1; vong < n; vong++)           // n - 1 vòng\n        for (int j = 0; j < m; j++)\n            if (dist[eu[j]] != INF && dist[eu[j]] + ew[j] < dist[ev[j]])\n                dist[ev[j]] = dist[eu[j]] + ew[j];  // nới cạnh j\n    for (int u = 1; u <= n; u++) cout << dist[u] << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"graph",dir:true,eu:"eu",ev:"ev",ew:"ew",n:"n",base:1,lab:"dist",ei:"j"}],py:{code:"n, m = 5, 7\neu = [1, 1, 2, 3, 3, 4, 5]\nev = [2, 3, 4, 2, 5, 5, 4]\new = [6, 7, 5, -4, -3, 2, 1]\nINF = float(\"inf\")\ndist = [INF] * (n + 1)\ndist[1] = 0\nfor vong in range(1, n):               # n - 1 vòng\n    for j in range(m):\n        if dist[eu[j]] != INF and dist[eu[j]] + ew[j] < dist[ev[j]]:\n            dist[ev[j]] = dist[eu[j]] + ew[j]   # nới cạnh j\nprint(*dist[1:])"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = 5, m = 7;\n        int[] eu = { 1, 1, 2, 3, 3, 4, 5 };\n        int[] ev = { 2, 3, 4, 2, 5, 5, 4 };\n        int[] ew = { 6, 7, 5, -4, -3, 2, 1 };\n        const long INF = long.MaxValue;\n        long[] dist = new long[n + 1];\n        Array.Fill(dist, INF);\n        dist[1] = 0;\n        for (int vong = 1; vong < n; vong++)  // n - 1 vòng\n            for (int j = 0; j < m; j++)\n                if (dist[eu[j]] != INF && dist[eu[j]] + ew[j] < dist[ev[j]])\n                    dist[ev[j]] = dist[eu[j]] + ew[j];   // nới cạnh j\n        for (int u = 1; u <= n; u++) Console.Write(dist[u] + \" \");\n        Console.WriteLine();\n    }\n}"}},{label:"Ví dụ: Dừng sớm khi không còn gì đổi",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n = 5, m = 7;\n    int eu[7] = {1, 1, 2, 3, 3, 4, 5};\n    int ev[7] = {2, 3, 4, 2, 5, 5, 4};\n    int ew[7] = {6, 7, 5, -4, -3, 2, 1};\n    const long long INF = 4e18;\n    vector<long long> dist(n + 1, INF);\n    dist[1] = 0;\n    int soVong = 0;\n    for (int vong = 1; vong < n; vong++) {\n        bool doi = false;\n        for (int j = 0; j < m; j++)\n            if (dist[eu[j]] != INF && dist[eu[j]] + ew[j] < dist[ev[j]]) {\n                dist[ev[j]] = dist[eu[j]] + ew[j];\n                doi = true;\n            }\n        soVong++;\n        if (!doi) break;               // vòng này không nới được gì: đã xong\n    }\n    cout << soVong << \" vong\\n\";\n    return 0;\n}",viz:[{type:"graph",dir:true,eu:"eu",ev:"ev",ew:"ew",n:"n",base:1,lab:"dist",ei:"j"},{type:"vars",names:["vong","doi"]}],py:{code:"n, m = 5, 7\neu = [1, 1, 2, 3, 3, 4, 5]\nev = [2, 3, 4, 2, 5, 5, 4]\new = [6, 7, 5, -4, -3, 2, 1]\nINF = float(\"inf\")\ndist = [INF] * (n + 1)\ndist[1] = 0\nso_vong = 0\nfor vong in range(1, n):\n    doi = False\n    for j in range(m):\n        if dist[eu[j]] != INF and dist[eu[j]] + ew[j] < dist[ev[j]]:\n            dist[ev[j]] = dist[eu[j]] + ew[j]\n            doi = True\n    so_vong += 1\n    if not doi:                        # vòng này không nới được gì: đã xong\n        break\nprint(so_vong, \"vong\")"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = 5, m = 7;\n        int[] eu = { 1, 1, 2, 3, 3, 4, 5 };\n        int[] ev = { 2, 3, 4, 2, 5, 5, 4 };\n        int[] ew = { 6, 7, 5, -4, -3, 2, 1 };\n        const long INF = long.MaxValue;\n        long[] dist = new long[n + 1];\n        Array.Fill(dist, INF);\n        dist[1] = 0;\n        int soVong = 0;\n        for (int vong = 1; vong < n; vong++)\n        {\n            bool doi = false;\n            for (int j = 0; j < m; j++)\n                if (dist[eu[j]] != INF && dist[eu[j]] + ew[j] < dist[ev[j]])\n                {\n                    dist[ev[j]] = dist[eu[j]] + ew[j];\n                    doi = true;\n                }\n            soVong++;\n            if (!doi) break;                   // vòng này không nới được gì: đã xong\n        }\n        Console.WriteLine(soVong + \" vong\");\n    }\n}"}},{label:"Ví dụ: Phát hiện chu trình âm",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n = 4, m = 5;\n    int eu[5] = {1, 2, 3, 4, 3};\n    int ev[5] = {2, 3, 4, 2, 1};\n    int ew[5] = {1, 2, -4, 1, 5};      // 2 -> 3 -> 4 -> 2 dài 2 - 4 + 1 = -1\n    const long long INF = 4e18;\n    vector<long long> dist(n + 1, INF);\n    dist[1] = 0;\n    for (int vong = 1; vong < n; vong++)\n        for (int j = 0; j < m; j++)\n            if (dist[eu[j]] != INF && dist[eu[j]] + ew[j] < dist[ev[j]])\n                dist[ev[j]] = dist[eu[j]] + ew[j];\n    bool am = false;\n    for (int j = 0; j < m; j++)        // vòng thứ n\n        if (dist[eu[j]] != INF && dist[eu[j]] + ew[j] < dist[ev[j]]) am = true;\n    cout << (am ? \"co chu trinh am\" : \"khong\") << \"\\n\";\n    return 0;\n}",viz:[{type:"graph",dir:true,eu:"eu",ev:"ev",ew:"ew",n:"n",base:1,lab:"dist",ei:"j"}],py:{code:"n, m = 4, 5\neu = [1, 2, 3, 4, 3]\nev = [2, 3, 4, 2, 1]\new = [1, 2, -4, 1, 5]                  # 2 -> 3 -> 4 -> 2 dài 2 - 4 + 1 = -1\nINF = float(\"inf\")\ndist = [INF] * (n + 1)\ndist[1] = 0\nfor vong in range(1, n):\n    for j in range(m):\n        if dist[eu[j]] != INF and dist[eu[j]] + ew[j] < dist[ev[j]]:\n            dist[ev[j]] = dist[eu[j]] + ew[j]\nam = any(dist[eu[j]] != INF and dist[eu[j]] + ew[j] < dist[ev[j]] for j in range(m))   # vòng thứ n\nprint(\"co chu trinh am\" if am else \"khong\")"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = 4, m = 5;\n        int[] eu = { 1, 2, 3, 4, 3 };\n        int[] ev = { 2, 3, 4, 2, 1 };\n        int[] ew = { 1, 2, -4, 1, 5 };         // 2 -> 3 -> 4 -> 2 dài 2 - 4 + 1 = -1\n        const long INF = long.MaxValue;\n        long[] dist = new long[n + 1];\n        Array.Fill(dist, INF);\n        dist[1] = 0;\n        for (int vong = 1; vong < n; vong++)\n            for (int j = 0; j < m; j++)\n                if (dist[eu[j]] != INF && dist[eu[j]] + ew[j] < dist[ev[j]])\n                    dist[ev[j]] = dist[eu[j]] + ew[j];\n        bool am = false;\n        for (int j = 0; j < m; j++)            // vòng thứ n\n            if (dist[eu[j]] != INF && dist[eu[j]] + ew[j] < dist[ev[j]]) am = true;\n        Console.WriteLine(am ? \"co chu trinh am\" : \"khong\");\n    }\n}"}},{label:"Ví dụ: Đi tối đa k cạnh",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n = 4, m = 5, k = 1;\n    int eu[5] = {1, 1, 2, 3, 2};\n    int ev[5] = {2, 3, 4, 4, 3};\n    int ew[5] = {1, 5, 1, 1, 1};\n    const long long INF = 4e18;\n    vector<long long> dist(n + 1, INF);\n    dist[1] = 0;\n    for (int vong = 1; vong <= k + 1; vong++) {      // tối đa k + 1 cạnh (k điểm dừng giữa đường)\n        vector<long long> cu = dist;                 // nới từ bản sao của vòng trước\n        for (int j = 0; j < m; j++)\n            if (cu[eu[j]] != INF && cu[eu[j]] + ew[j] < dist[ev[j]])\n                dist[ev[j]] = cu[eu[j]] + ew[j];\n    }\n    cout << dist[4] << \"\\n\";\n    return 0;\n}",viz:[{type:"graph",dir:true,eu:"eu",ev:"ev",ew:"ew",n:"n",base:1,lab:"dist",ei:"j"},{type:"cells",of:"cu"}],py:{code:"n, m, k = 4, 5, 1\neu = [1, 1, 2, 3, 2]\nev = [2, 3, 4, 4, 3]\new = [1, 5, 1, 1, 1]\nINF = float(\"inf\")\ndist = [INF] * (n + 1)\ndist[1] = 0\nfor vong in range(k + 1):              # tối đa k + 1 cạnh (k điểm dừng giữa đường)\n    cu = dist[:]                       # nới từ bản sao của vòng trước\n    for j in range(m):\n        if cu[eu[j]] != INF and cu[eu[j]] + ew[j] < dist[ev[j]]:\n            dist[ev[j]] = cu[eu[j]] + ew[j]\nprint(dist[4])"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = 4, m = 5, k = 1;\n        int[] eu = { 1, 1, 2, 3, 2 };\n        int[] ev = { 2, 3, 4, 4, 3 };\n        int[] ew = { 1, 5, 1, 1, 1 };\n        const long INF = long.MaxValue;\n        long[] dist = new long[n + 1];\n        Array.Fill(dist, INF);\n        dist[1] = 0;\n        for (int vong = 1; vong <= k + 1; vong++)   // tối đa k + 1 cạnh (k điểm dừng giữa đường)\n        {\n            long[] cu = (long[])dist.Clone();  // nới từ bản sao của vòng trước\n            for (int j = 0; j < m; j++)\n                if (cu[eu[j]] != INF && cu[eu[j]] + ew[j] < dist[ev[j]])\n                    dist[ev[j]] = cu[eu[j]] + ew[j];\n        }\n        Console.WriteLine(dist[4]);\n    }\n}"}},{label:"Lỗi: nới từ đỉnh chưa tới được",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n = 3, m = 2;\n    int eu[2] = {2, 1};\n    int ev[2] = {3, 2};\n    int ew[2] = {-5, 4};\n    const int INF = 1000000000;\n    int dist[4] = {0, 0, INF, INF};\n    for (int j = 0; j < m; j++)        // chỉ chạy một vòng, theo thứ tự cạnh trên\n        if (dist[eu[j]] + ew[j] < dist[ev[j]])   // SAI: thiếu dist[eu[j]] != INF\n            dist[ev[j]] = dist[eu[j]] + ew[j];\n    cout << dist[3] << \"\\n\";\n    return 0;\n}",viz:[{type:"graph",dir:true,eu:"eu",ev:"ev",ew:"ew",n:"n",base:1,lab:"dist",ei:"j"}],py:{code:"n, m = 3, 2\neu = [2, 1]\nev = [3, 2]\new = [-5, 4]\nINF = 10**9\ndist = [0, 0, INF, INF]\nfor j in range(m):                     # chỉ chạy một vòng, theo thứ tự cạnh trên\n    if dist[eu[j]] + ew[j] < dist[ev[j]]:   # SAI: thiếu dist[eu[j]] != INF\n        dist[ev[j]] = dist[eu[j]] + ew[j]\nprint(dist[3])"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int m = 2;\n        int[] eu = { 2, 1 };\n        int[] ev = { 3, 2 };\n        int[] ew = { -5, 4 };\n        const int INF = 1000000000;\n        int[] dist = { 0, 0, INF, INF };\n        for (int j = 0; j < m; j++)            // chỉ chạy một vòng, theo thứ tự cạnh trên\n            if (dist[eu[j]] + ew[j] < dist[ev[j]])   // SAI: thiếu dist[eu[j]] != INF\n                dist[ev[j]] = dist[eu[j]] + ew[j];\n        Console.WriteLine(dist[3]);\n    }\n}"}}];
const sim57=makeSim2(document.getElementById("sim-l57"),{id:"s57",presets:PR57});
makeEx2(document.getElementById("ex-l57"),sim57,[{t:"Ví điện tử",d:"Trong một trò chơi, đi từ ô u sang ô v (một chiều) làm số xu thay đổi w (w âm là được thưởng). Tổng chi phí của một đường là tổng các w. Đảm bảo không có vòng nào có tổng âm. Đầu vào: n m (1 ≤ n ≤ 1000, 0 ≤ m ≤ 5000) rồi m dòng u v w (|w| ≤ 10^6). Đầu ra: một dòng n giá trị: chi phí nhỏ nhất từ ô 1 tới ô i, hoặc INF nếu không tới được.",tests:[{in:"5 7\n1 2 6\n1 3 7\n2 4 5\n3 2 -4\n3 5 -3\n4 5 2\n5 4 1",out:"0 3 7 5 4"},{in:"3 2\n2 3 -5\n1 2 4",out:"0 4 -1"},{in:"4 0\n",out:"0 INF INF INF"},{in:"4 4\n4 3 -1\n3 2 -1\n2 1 -1\n1 4 5",out:"0 3 4 5"},{in:"30 80\n22 30 7\n22 20 8\n15 2 6\n24 8 8\n23 15 8\n5 6 -3\n19 12 -2\n30 16 -4\n15 7 -10\n7 10 4\n4 30 -9\n21 14 4\n6 8 -9\n7 11 7\n4 13 -1\n4 25 1\n23 10 9\n9 11 -10\n29 16 -5\n18 22 11\n15 16 -2\n24 11 -10\n9 11 3\n22 5 8\n18 11 13\n28 8 -9\n9 21 -4\n22 16 17\n5 13 11\n18 19 8\n24 26 -10\n28 24 14\n7 11 7\n24 2 20\n3 7 -5\n30 26 17\n24 14 3\n6 1 17\n5 15 15\n22 30 12\n28 1 -9\n5 12 -6\n4 12 -10\n8 20 18\n7 19 18\n4 28 8\n10 19 13\n9 10 9\n27 23 12\n21 29 2\n30 26 2\n24 30 13\n21 23 13\n27 30 3\n13 16 -10\n11 12 5\n15 6 -7\n3 15 11\n30 19 -10\n3 9 12\n18 6 -10\n10 2 13\n3 12 11\n18 11 -5\n7 17 10\n4 27 -5\n18 8 1\n8 1 16\n24 17 15\n5 30 -10\n4 26 18\n18 30 11\n5 25 -1\n13 11 13\n16 12 6\n29 19 16\n24 9 19\n18 29 20\n22 27 10\n10 8 -10",out:"0 INF INF INF INF INF INF INF INF INF INF INF INF INF INF INF INF INF INF INF INF INF INF INF INF INF INF INF INF INF"}],start:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n, m;\n    cin >> n >> m;\n    vector<int> eu(m), ev(m);\n    vector<long long> ew(m);\n    for (int j = 0; j < m; j++) cin >> eu[j] >> ev[j] >> ew[j];\n    const long long INF = 4e18;\n    vector<long long> dist(n + 1, INF);\n    dist[1] = 0;\n    // n - 1 vòng nới mọi cạnh (bỏ qua cạnh xuất phát từ đỉnh dist = INF)\n    for (int u = 1; u <= n; u++) {\n        if (dist[u] == INF) cout << \"INF \";\n        else cout << dist[u] << \" \";\n    }\n    cout << \"\\n\";\n    return 0;\n}",py:{start:"n, m = map(int, input().split())\neu, ev, ew = [], [], []\nfor _ in range(m):\n    u, v, w = map(int, input().split())\n    eu.append(u)\n    ev.append(v)\n    ew.append(w)\nINF = float(\"inf\")\ndist = [INF] * (n + 1)\ndist[1] = 0\n# n - 1 vòng nới mọi cạnh (bỏ qua cạnh xuất phát từ đỉnh dist = INF)\nprint(*(\"INF\" if d == INF else d for d in dist[1:]))",hints:["Cạnh âm nên Dijkstra không dùng được. Bellman-Ford: n − 1 vòng, mỗi vòng nới mọi cạnh.","Chỉ nới cạnh u → v khi dist[u] ≠ INF.","Thêm cờ “vòng này có đổi gì không” để dừng sớm."]},cs:{start:"using System;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] nm = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int n = nm[0], m = nm[1];\n        int[] eu = new int[m], ev = new int[m];\n        long[] ew = new long[m];\n        for (int j = 0; j < m; j++)\n        {\n            long[] e = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n            eu[j] = (int)e[0]; ev[j] = (int)e[1]; ew[j] = e[2];\n        }\n        const long INF = long.MaxValue;\n        long[] dist = new long[n + 1];\n        Array.Fill(dist, INF);\n        dist[1] = 0;\n        // n - 1 vòng nới mọi cạnh (bỏ qua cạnh xuất phát từ đỉnh dist = INF)\n        var sb = new StringBuilder();\n        for (int u = 1; u <= n; u++) sb.Append(dist[u] == INF ? \"INF\" : dist[u].ToString()).Append(' ');\n        Console.WriteLine(sb.ToString());\n    }\n}",hints:["Cạnh âm nên Dijkstra không dùng được. Bellman-Ford: n − 1 vòng, mỗi vòng nới mọi cạnh.","Chỉ nới cạnh u → v khi dist[u] ≠ INF (với long.MaxValue, cộng thêm số dương còn bị tràn số).","Thêm cờ “vòng này có đổi gì không” để dừng sớm."]}},{t:"Máy in tiền",d:"Một sàn đổi đồ: m giao dịch “u v w” nghĩa là đổi món u lấy món v thì lời −w (w là chi phí, có thể âm). Có tồn tại một vòng giao dịch đi rồi quay về đúng món ban đầu mà tổng chi phí âm (lời mãi không dừng) không? Vòng có thể bắt đầu ở bất kỳ món nào. Đầu vào: n m (1 ≤ n ≤ 500, 0 ≤ m ≤ 5000) rồi m dòng u v w (|w| ≤ 10^6). Đầu ra: YES hoặc NO.",tests:[{in:"4 5\n1 2 1\n2 3 2\n3 4 -4\n4 2 1\n3 1 5",out:"YES"},{in:"5 7\n1 2 6\n1 3 7\n2 4 5\n3 2 -4\n3 5 -3\n4 5 2\n5 4 1",out:"NO"},{in:"3 2\n2 3 1\n3 2 -2",out:"YES"},{in:"2 1\n1 1 -1",out:"YES"},{in:"3 0\n",out:"NO"},{in:"25 60\n17 22 -5\n23 22 1\n10 18 15\n2 21 -3\n7 24 16\n3 9 18\n23 15 15\n7 20 -3\n19 6 15\n2 6 12\n19 10 6\n7 9 10\n8 14 18\n2 22 10\n25 6 2\n17 8 11\n16 17 0\n8 6 12\n13 17 12\n12 18 -7\n13 3 9\n2 3 1\n1 15 -1\n19 3 17\n1 21 -7\n9 18 7\n14 6 12\n13 20 -3\n24 15 17\n23 18 12\n23 6 13\n14 21 -9\n16 10 -2\n7 24 15\n17 15 9\n11 14 8\n3 21 7\n1 24 0\n16 22 -3\n19 20 5\n13 9 2\n25 24 13\n24 18 13\n20 15 15\n8 6 -9\n7 23 2\n17 15 -6\n7 9 -3\n17 24 -6\n19 12 -5\n3 22 7\n12 15 17\n1 15 15\n2 6 2\n10 5 -1\n22 18 -2\n8 14 2\n17 21 18\n25 8 -8\n13 10 5",out:"NO"}],start:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n, m;\n    cin >> n >> m;\n    vector<int> eu(m), ev(m);\n    vector<long long> ew(m);\n    for (int j = 0; j < m; j++) cin >> eu[j] >> ev[j] >> ew[j];\n    vector<long long> dist(n + 1, 0);  // nguồn ảo: mọi đỉnh bắt đầu từ 0\n    // n - 1 vòng nới, rồi vòng thứ n: còn nới được là có chu trình âm\n    cout << \"NO\" << \"\\n\";\n    return 0;\n}",py:{start:"n, m = map(int, input().split())\neu, ev, ew = [], [], []\nfor _ in range(m):\n    u, v, w = map(int, input().split())\n    eu.append(u)\n    ev.append(v)\n    ew.append(w)\ndist = [0] * (n + 1)                   # nguồn ảo: mọi đỉnh bắt đầu từ 0\n# n - 1 vòng nới, rồi vòng thứ n: còn nới được là có chu trình âm\nprint(\"NO\")",hints:["Vòng có thể ở bất kỳ đâu: khởi tạo dist = 0 cho mọi đỉnh (như một nguồn ảo nối tới tất cả).","Chạy n − 1 vòng nới, rồi thêm vòng thứ n: còn cạnh nới được thì có chu trình âm.","Khuyên u → u có w < 0 cũng là chu trình âm."]},cs:{start:"using System;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] nm = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int n = nm[0], m = nm[1];\n        int[] eu = new int[m], ev = new int[m];\n        long[] ew = new long[m];\n        for (int j = 0; j < m; j++)\n        {\n            long[] e = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n            eu[j] = (int)e[0]; ev[j] = (int)e[1]; ew[j] = e[2];\n        }\n        long[] dist = new long[n + 1];         // nguồn ảo: mọi đỉnh bắt đầu từ 0\n        // n - 1 vòng nới, rồi vòng thứ n: còn nới được là có chu trình âm\n        Console.WriteLine(\"NO\");\n    }\n}",hints:["Vòng có thể ở bất kỳ đâu: khởi tạo dist = 0 cho mọi đỉnh (như một nguồn ảo nối tới tất cả).","Chạy n − 1 vòng nới, rồi thêm vòng thứ n: còn cạnh nới được thì có chu trình âm.","Khuyên u → u có w < 0 cũng là chu trình âm."]}},{t:"Bay tiết kiệm với số chặng giới hạn",d:"Có n sân bay và m chuyến bay một chiều u → v giá w. Đầu vào: n m (1 ≤ n ≤ 500, 0 ≤ m ≤ 5000), m dòng u v w (1 ≤ w ≤ 10^6), rồi dòng s t k. Đầu ra: giá rẻ nhất để bay từ s tới t mà dừng ở tối đa k sân bay trung gian (tức dùng tối đa k + 1 chuyến), hoặc -1 nếu không được.",tests:[{in:"4 5\n1 2 1\n1 3 5\n2 4 1\n3 4 1\n2 3 1\n1 4 1",out:"2"},{in:"4 4\n1 2 1\n2 3 1\n3 4 1\n1 4 10\n1 4 1",out:"10"},{in:"4 4\n1 2 1\n2 3 1\n3 4 1\n1 4 10\n1 4 2",out:"3"},{in:"3 1\n1 2 5\n1 3 5",out:"-1"},{in:"3 2\n1 2 5\n2 3 5\n1 3 0",out:"-1"},{in:"20 60\n1 20 8\n18 11 12\n19 11 21\n17 10 45\n4 14 36\n18 4 47\n5 1 43\n18 4 33\n6 20 9\n15 17 9\n5 6 8\n5 12 44\n8 6 16\n10 13 7\n17 11 40\n10 5 23\n3 18 33\n19 11 26\n1 15 42\n13 15 43\n11 6 35\n13 7 33\n19 9 23\n5 10 3\n1 12 10\n10 11 8\n3 10 49\n18 13 46\n10 11 38\n2 3 16\n14 4 31\n20 12 20\n20 15 49\n15 1 2\n4 20 34\n12 20 20\n15 20 36\n16 6 16\n1 17 18\n18 1 45\n16 9 5\n5 14 31\n19 14 17\n18 14 29\n9 11 39\n15 14 7\n8 1 44\n16 5 16\n4 1 13\n8 17 41\n14 8 18\n13 20 29\n8 14 47\n3 10 28\n4 9 32\n3 20 1\n9 20 5\n9 10 44\n12 18 42\n15 8 24\n1 20 3",out:"8"}],start:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n, m;\n    cin >> n >> m;\n    vector<int> eu(m), ev(m);\n    vector<long long> ew(m);\n    for (int j = 0; j < m; j++) cin >> eu[j] >> ev[j] >> ew[j];\n    int s, t, k;\n    cin >> s >> t >> k;\n    const long long INF = 4e18;\n    vector<long long> dist(n + 1, INF);\n    dist[s] = 0;\n    // k + 1 vòng; mỗi vòng nới từ bản sao dist của vòng trước\n    cout << -1 << \"\\n\";\n    return 0;\n}",py:{start:"n, m = map(int, input().split())\neu, ev, ew = [], [], []\nfor _ in range(m):\n    u, v, w = map(int, input().split())\n    eu.append(u)\n    ev.append(v)\n    ew.append(w)\ns, t, k = map(int, input().split())\nINF = float(\"inf\")\ndist = [INF] * (n + 1)\ndist[s] = 0\n# k + 1 vòng; mỗi vòng nới từ bản sao dist của vòng trước\nprint(-1)",hints:["Sau vòng thứ i của Bellman-Ford (nới đúng cách), dist[v] là giá rẻ nhất dùng tối đa i chuyến. Chạy k + 1 vòng.","Mỗi vòng phải nới từ bản sao cu = dist[:] của vòng trước.","Dijkstra thường không giữ được ràng buộc số chặng."]},cs:{start:"using System;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] nm = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int n = nm[0], m = nm[1];\n        int[] eu = new int[m], ev = new int[m];\n        long[] ew = new long[m];\n        for (int j = 0; j < m; j++)\n        {\n            long[] e = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n            eu[j] = (int)e[0]; ev[j] = (int)e[1]; ew[j] = e[2];\n        }\n        int[] stk = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int s = stk[0], t = stk[1], k = stk[2];\n        const long INF = long.MaxValue;\n        long[] dist = new long[n + 1];\n        Array.Fill(dist, INF);\n        dist[s] = 0;\n        // k + 1 vòng; mỗi vòng nới từ bản sao dist của vòng trước\n        Console.WriteLine(-1);\n    }\n}",hints:["Sau vòng thứ i của Bellman-Ford (nới đúng cách), dist[v] là giá rẻ nhất dùng tối đa i chuyến. Chạy k + 1 vòng.","Mỗi vòng phải nới từ bản sao (long[])dist.Clone() của vòng trước.","Dijkstra thường không giữ được ràng buộc số chặng."]}}]);

makeQuiz("quiz57","score57",[{"q": "Bellman-Ford cần bao nhiêu vòng nới (không có chu trình âm)?", "o": ["1", "log n", "n − 1", "m"], "a": 2, "e": "Đường ngắn nhất không lặp đỉnh dùng tối đa n − 1 cạnh."}, {"q": "Vòng nới thứ n vẫn làm một dist giảm. Kết luận?", "o": ["Thuật toán sai", "Có chu trình âm tới được", "Đồ thị không liên thông", "Cần thêm một vòng nữa"], "a": 1, "e": "Không có chu trình âm thì n − 1 vòng đã đủ."}, {"q": "Vì sao phải kiểm tra dist[u] ≠ ∞ trước khi nới?", "o": ["Để chạy nhanh hơn", "∞ cộng số âm vẫn nhỏ hơn ∞, tạo ra khoảng cách giả", "Để tránh chia cho 0", "Không cần"], "a": 1, "e": "Đỉnh chưa tới được không được làm nguồn cho đỉnh khác."}, {"q": "Độ phức tạp của Bellman-Ford?", "o": ["O(n + m)", "O(m log n)", "O(n · m)", "O(n³)"], "a": 2, "e": "n − 1 vòng, mỗi vòng m cạnh."}]);

